"""Locate a usable fastText engine and expose train/test helpers.

The paper's system *is* the authors' own C++ fastText supervised trainer, so
the preferred engine is that exact code.  On this host (Windows 11, no
make/g++/clang/cmake) the native build path of repo/setup.py is unavailable,
so we fall back to `fasttext-wheel`, a prebuilt binary wheel of the same
facebookresearch/fastText 0.9.2 C++ sources plus the official Python binding.
Every hyper-parameter is forwarded verbatim; no author code is modified.

Engine preference order (recorded in the returned provenance dict):
  1. an already importable `fasttext` module
  2. `pip install fasttext-wheel` (prebuilt wheel of the same C++ trainer)
  3. a native build of repo/ (`make`, or `pip install .`)
  4. the authors' PyTorch EmbeddingBag example  -> re-implementation, would
     downgrade the verdict to partially_reproduced
"""

import importlib
import json
import os
import subprocess
import sys

REPO = os.path.join(os.path.dirname(os.path.abspath(__file__)), "repo")


def _try_import():
    try:
        import fasttext  # noqa: F401
        return fasttext
    except Exception:
        return None


def _try_pip_wheel():
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "--quiet",
                        "fasttext-wheel"], check=True, timeout=600,
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except Exception:
        return None
    importlib.invalidate_caches()
    return _try_import()


def _try_native_build():
    for cmd in (["make", "-C", REPO], [sys.executable, "setup.py", "build_ext", "--inplace"]):
        try:
            subprocess.run(cmd, cwd=REPO, check=True, timeout=1800,
                           stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        except Exception:
            continue
        mod = _try_import()
        if mod is not None:
            return mod
    return None


def get_engine():
    """Return (fasttext_module, provenance_dict)."""
    attempts = []

    mod = _try_import()
    if mod is not None:
        attempts.append("import fasttext: ok")
        return mod, _provenance(mod, "importable fasttext module", attempts)

    attempts.append("import fasttext: not available")
    mod = _try_pip_wheel()
    if mod is not None:
        attempts.append("pip install fasttext-wheel: ok")
        return mod, _provenance(mod, "fasttext-wheel (prebuilt wheel of the "
                                     "facebookresearch/fastText 0.9.2 C++ trainer)", attempts)

    attempts.append("pip install fasttext-wheel: failed")
    mod = _try_native_build()
    if mod is not None:
        attempts.append("native build of repo/: ok")
        return mod, _provenance(mod, "native build of repo/ (authors' C++ sources)", attempts)

    attempts.append("native build of repo/: failed")
    raise RuntimeError("no usable fastText engine; attempts: " + "; ".join(attempts))


def _provenance(mod, how, attempts):
    prov = {
        "engine": how,
        "module_file": getattr(mod, "__file__", None),
        "attempts": attempts,
    }
    try:
        import importlib.metadata as md
        for dist in md.distributions():
            name = (dist.metadata["Name"] or "").lower()
            if name in ("fasttext", "fasttext-wheel", "fasttext-wheel-unofficial"):
                prov["distribution"] = "%s %s" % (dist.metadata["Name"], dist.version)
                break
    except Exception:
        pass
    return prov


# --------------------------------------------------------------------------
# thin wrappers
# --------------------------------------------------------------------------
def train(ft, input_path, **kwargs):
    kwargs.setdefault("verbose", 2)
    return ft.train_supervised(input=input_path, **kwargs)


def test(model, path):
    """Return (N, precision@1, recall@1) exactly as the authors' `fasttext test`."""
    return model.test(path)


def describe(model):
    return {
        "dim": model.get_dimension(),
        "words": len(model.get_words()),
        "labels": sorted(model.get_labels()),
    }


if __name__ == "__main__":
    m, p = get_engine()
    print(json.dumps(p, indent=2))

